{
  "scenario": "Приём наличных от клиента",
  "timeline": [
    {"t": 0.0, "event": "Кассир сидит за рабочим столом, дверь кассы закрыта."},
    {"t": 2.0, "event": "Внезапно появляется клиент (мужчина в светлой рубашке) за стеклянной дверью."},
    {"t": 5.4, "event": "Клиент открывает дверь кассового узла и входит внутрь."},
    {"t": 5.7, "event": "Клиент закрывает за собой дверь кассы."},
    {"t": 8.1, "event": "Клиент подходит к столу и кладёт на стол пачку наличных денег."},
    {"t": 9.1, "event": "Кассир начинает пересчитывать деньги на счётной машине."},
    {"t": 12.1, "event": "Кассир продолжает работу со счётной машиной, клиент наблюдает."},
    {"t": 15.8, "event": "Операция с пересчётом продолжается, клиенты находятся на своих местах."}
  ],
  "violations": [
    {
      "type_id": "door_left_open",
      "timecode_sec": 5.4,
      "confidence": 0.9,
      "obs": "Дверь кассы открыта в течение нескольких секунд (с 5.4 до 5.7 с), пока клиент входит и закрывает её. Хотя это кратковременное действие при входе, дверь была открыта."
    },
    {
      "type_id": "no_client_id_check",
      "timecode_sec": 8.1,
      "confidence": 0.8,
      "obs": "Клиент кладёт наличные на стол, но кассир не видит, чтобы клиент предъявлял документ, удостоверяющий личность, и не проверяет его перед началом пересчёта денег."
    }
  ]
}
